import {
  ArrowDownRight,
  ArrowUpRight,
  Code2,
  Cpu,
  Layers,
  Sparkles,
  Zap
} from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { Link } from "react-router-dom";
import BuildAnimation from "../components/build-animation/BuildAnimation";
import InteractiveCompareSlider from "../components/build-animation/InteractiveCompareSlider";
import { HeroAgentStudio } from "../components/hero/HeroAgentStudio";

const BANGALORE_LOCATION = "Bangalore, India";
const getTag = (num: string) => `// ${num}`;

interface WorkItem {
  id: string;
  number: string;
  title: string;
  category: string;
  description: string;
  link: string;
  bgColor: string;
  strokeColor: string;
}

const SELECTED_PROJECTS: WorkItem[] = [
  {
    id: "volvo",
    number: "01",
    title: "VOLVO PARTNER CONNECT 2.0",
    category: "ENTERPRISE DATA · DESIGN SYSTEM · DATA VISUALIZATION",
    description:
      "Connected enterprise dashboards and analytics experiences simplifying dealer operations, tracking KPIs, and supporting data-driven decisions.",
    link: "/volvo",
    bgColor: "bg-[#ff5a43]",
    strokeColor: "#1a1a1a"
  },
  {
    id: "advitiix",
    number: "02",
    title: "ADVITIIX MANAGEMENT TOOL",
    category: "FOUNDING PRODUCT · FULL-STACK SUITE · 0 TO 1",
    description:
      "Sole founding designer and frontend engineer crafting end-to-end UX/UI, UX writing, and code across Admin, PM, Employee, and Food operations.",
    link: "/advitiix",
    bgColor: "bg-[#d6cebf]",
    strokeColor: "#222222"
  },
  {
    id: "car-3d",
    number: "03",
    title: "3D CAR DESIGN & X-RAY EXPERIENCE",
    category: "INTERACTIVE 3D · THREE.JS & WEBGL · HARDWARE",
    description:
      "Engineered real-time 3D vehicle platform solving WebGL polygon rendering bottlenecks with dual assembled and X-ray component diagnostics.",
    link: "/car-3d",
    bgColor: "bg-[#8fa88b]",
    strokeColor: "#1f2a1e"
  },
  {
    id: "model-pipeline",
    number: "04",
    title: "MODEL PIPELINE & AI DASHBOARDS",
    category: "AI & TELEMETRY · ENTERPRISE · DATA VISUALIZATION",
    description:
      "Real-time ML model pipeline monitoring dashboards, automated product newsletters, and complex telemetry data visualization for high-velocity teams.",
    link: "/model-pipeline",
    bgColor: "bg-[#8ea2b8]",
    strokeColor: "#1c2430"
  },
  {
    id: "fire",
    number: "05",
    title: "FIRE & SMOKE DETECTION PLATFORM",
    category: "INDUSTRIAL IOT · SPATIAL MONITORING · INCIDENT RESPONSE",
    description:
      "Redesigning industrial incident monitoring around physical sensor locations, thermal camera telemetry, and rapid emergency response dispatch.",
    link: "/fire",
    bgColor: "bg-[#d4b067]",
    strokeColor: "#2a2212"
  },
  {
    id: "finora",
    number: "06",
    title: "PAYMI AI FINANCIAL INTELLIGENCE",
    category: "FINTECH · PREDICTIVE ANALYTICS · MOBILE & AI",
    description:
      "Conversational AI banking assistant and predictive cashflow diagnostics helping modern users understand spending, manage runway, and optimize savings.",
    link: "/finora",
    bgColor: "bg-[#b4a3cb]",
    strokeColor: "#231e2b"
  }
];

const METADATA_ITEMS = [
  { label: "FOCUS", value: "Enterprise UX · Design Systems · Data Visualization" },
  { label: "STACK", value: "React · TypeScript · Tailwind · Three.js · Node" },
  { label: "ROLE", value: "Sole Founding Designer & Frontend Engineer" },
  { label: "LOCATION", value: "Bangalore, Karnataka, India" },
  { label: "STATUS", value: "Open to design engineering & product design leadership" }
];

const CAPABILITIES = [
  {
    num: "01",
    title: "PRODUCT & UX STRATEGY",
    skills: [
      "Enterprise Dashboard UX",
      "Multi-Role Permissions Systems",
      "Design Systems & Token Architecture",
      "Wireframing & Interactive Prototyping",
      "Information Hierarchy & UX Writing",
      "User Task Flows & Friction Auditing"
    ]
  },
  {
    num: "02",
    title: "FRONTEND & CODE ARCHITECTURE",
    skills: [
      "React 18+ · TypeScript · Next.js",
      "Modern Tailwind CSS & Design Tokens",
      "Component Modularization & State Design",
      "API Integration & WebSocket Feeds",
      "Performance Profiling & Bundle Hygiene",
      "Clean Git Workflows & Deployment"
    ]
  },
  {
    num: "03",
    title: "SPECIALIZED & 3D SYSTEMS",
    skills: [
      "Three.js & WebGL 3D Visualization",
      "Model Polygon & Texture Budgeting",
      "X-Ray & Assembled Diagnostic Views",
      "AI Pipeline Telemetry & Metric Visuals",
      "Automated Digest & Newsletter Engines",
      "High-Density Dark & Light Themes"
    ]
  }
];

const TIMELINE = [
  {
    period: "OCT 2025 — PRESENT",
    company: "Advitiix Technovate",
    role: "Sole Product Designer & Developer",
